// One offer-approval request per sub-workflow execution.
const items = $input.all();
if (items.length !== 1) throw new Error(`Offer Approval expects 1 candidate item per execution; got ${items.length}.`);
const raw = items[0].json || {};
const candidateId = String(raw.candidateId ?? raw.candidate_id ?? '').trim();
const managerEmail = String(raw.managerEmail ?? raw.manager_email ?? '').trim();
const offerId = String(raw.offerId ?? raw.offer_id ?? `OFR-${candidateId}`).trim();
const jobId = String(raw.jobId ?? raw.job_id ?? '').trim();
const actor = String(raw.actor ?? 'Hiring Manager').trim();
if (!/^[A-Za-z0-9_-]+$/.test(candidateId)) throw new Error('Candidate ID is missing or contains unsupported characters.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(managerEmail)) throw new Error('managerEmail is required (valid hiring-manager email).');
if (!/^[A-Za-z0-9_-]+$/.test(offerId)) throw new Error('offerId must be alphanumeric, hyphen, or underscore.');
const currentState = String(raw.currentState ?? raw.current_state ?? 'OFFER').trim().toUpperCase();
if (currentState !== 'OFFER') throw new Error(`Offer approval requires currentState OFFER. Got: ${currentState}`);
return [{json:{
 candidateId,managerEmail,offerId,jobId,actor,
 requestState:currentState,
 sendCandidateNotification:raw.sendCandidateNotification === true,
 allowCandidateCommunication:raw.allowCandidateCommunication === true,
 airtableCandidateFilter:`{Candidate ID} = '${candidateId}'`,
 requestedAt:new Date().toISOString()
}}];

const rows=$input.all().filter(x=>x.json && x.json.id);
if(rows.length !== 1) throw new Error(`Expected exactly one Airtable Candidates record, got ${rows.length}. Check Candidate ID and duplicate records.`);
const candidate=rows[0].json; const fields=candidate.fields ?? candidate;
const request=$('01 | Normalize Offer Request').first().json;
const actualId=String(fields['Candidate ID'] ?? '').trim();
const state=String(fields['Current State'] ?? '').trim().toUpperCase();
if(actualId !== request.candidateId) throw new Error(`Candidate mismatch: expected ${request.candidateId}, found ${actualId}`);
if(state !== 'OFFER') throw new Error(`Candidate ${actualId} has state ${state}; move to OFFER via your state manager before approval.`);
const email=String(fields['Email'] ?? '').trim();
const fullName=String(fields['Full Name'] ?? '').trim();
const isMock=fields['Is Mock Evaluation'] === true;
const canNotify=request.sendCandidateNotification && request.allowCandidateCommunication && !isMock && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && !/@example\.(com|org|net)$/i.test(email);
return [{json:{...request,candidateRecordId:candidate.id,candidateEmail:email,candidateName:fullName,candidateState:state,isMockEvaluation:isMock,canNotify}}];

